import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../Styles/UserProfile.css";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { bankCardSchema } from "../Validations/Bank";

const CompanyProfile = () => {
  const navigate = useNavigate();

  const [company, setCompany] = useState({});
  const [preview, setPreview] = useState(null);
  const [showCardModal, setShowCardModal] = useState(false);

  const {
    register,
    handleSubmit,
    setValue,
    reset,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(bankCardSchema),
  });

  // Load profile
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));
    if (!saved?.email) {
      navigate("/login");
      return;
    }

    axios
      .get(`http://localhost:3001/company/${saved.email}`)
      .then((res) => {
        setCompany(res.data);

        const bank = res.data.bankInfo || {};
        reset({
          selectedBank: bank.bankName || "",
          cardNumber: bank.cardNumber || "",
          cardName: bank.cardName || "",
          expiry: bank.expiry || "",
          cvv: bank.cvv || "",
        });
      })
      .catch(() => alert("Failed to load company"));
  }, [navigate, reset]);

  // Upload profile image
  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const form = new FormData();
    form.append("file", file);
    form.append("email", company.email);
    form.append("type", "profile");

    try {
      const res = await axios.post(
        "http://localhost:3001/uploadCompanyFile",
        form,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      setCompany((prev) => ({ ...prev, profileImage: res.data.fileUrl }));
      setPreview(res.data.fileUrl);

      alert("Profile photo updated!");
    } catch {
      alert("Failed to upload image");
    }
  };

  // Upload License
  const handleLicenseUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const form = new FormData();
    form.append("file", file);
    form.append("email", company.email);
    form.append("type", "license");

    try {
      const res = await axios.post(
        "http://localhost:3001/uploadCompanyFile",
        form,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      setCompany((prev) => ({ ...prev, licenseFile: res.data.fileUrl }));
      alert("License uploaded successfully!");
    } catch {
      alert("Failed to upload license");
    }
  };

  // Delete License
  const deleteLicense = async () => {
    if (!window.confirm("Delete business license?")) return;

    try {
      await axios.post(`http://localhost:3001/company/${company.email}/bank`, {
        licenseFile: "",
      });

      setCompany((prev) => ({ ...prev, licenseFile: null }));
      alert("License deleted!");
    } catch {
      alert("Error deleting license");
    }
  };

  // Save Bank Card
  const saveCardInfo = async (data) => {
    try {
      await axios.post(`http://localhost:3001/company/${company.email}/bank`, {
        bankName: data.selectedBank,
        cardNumber: data.cardNumber,
        cardName: data.cardName,
        expiry: data.expiry,
        cvv: data.cvv,
      });

      alert("Bank information saved!");

      setCompany((prev) => ({
        ...prev,
        bankInfo: {
          bankName: data.selectedBank,
          cardNumber: data.cardNumber,
          cardName: data.cardName,
          expiry: data.expiry,
          cvv: data.cvv,
        },
      }));

      setShowCardModal(false);
    } catch {
      alert("Failed to save bank info");
    }
  };

  // Delete Bank Card
  const deleteBankCard = async () => {
    if (!window.confirm("Delete saved card?")) return;

    try {
      await axios.post(`http://localhost:3001/company/${company.email}/bank`, {
        bankName: "",
        cardNumber: "",
        cardName: "",
        expiry: "",
        cvv: "",
      });

      setCompany((prev) => ({ ...prev, bankInfo: null }));
      reset();

      alert("Bank card deleted.");
    } catch {
      alert("Failed to delete card");
    }
  };

  return (
    <div className="profile-page">
      {/* PROFILE */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-img-container">
            <img
              src={
                preview ||
                company.profileImage ||
                "https://cdn-icons-png.flaticon.com/512/3135/3135768.png"
              }
              className="profile-img"
              alt=""
            />

            <label htmlFor="companyImg" className="upload-circle-C">
              📷
            </label>
            <input
              type="file"
              id="companyImg"
              accept="image/*"
              onChange={handleImageUpload}
              style={{ display: "none" }}
            />
          </div>

          <div>
            <h2 className="profile-name">{company.companyName}</h2>
            <p className="profile-email">{company.email}</p>
            <p className="profile-detail">
              {company.industry} • {company.location}
            </p>
          </div>
        </div>
      </div>

      {/* LICENSE */}
      <div className="payment-box">
        <h3>Business License</h3>

        {company.licenseFile ? (
          <div className="cv-section">
            <p className="cv-success">License Uploaded Successfully</p>

            <div className="cv-actions">
              <a
                href={company.licenseFile}
                target="_blank"
                className="cv-btn view"
              >
                View
              </a>

              <label htmlFor="licenseUpload" className="cv-btn replace">
                Replace
              </label>

              <button className="cv-btn delete" onClick={deleteLicense}>
                Delete
              </button>

              <input
                type="file"
                id="licenseUpload"
                accept=".pdf"
                style={{ display: "none" }}
                onChange={handleLicenseUpload}
              />
            </div>
          </div>
        ) : (
          <>
            <input
              id="licenseUpload"
              type="file"
              accept=".pdf"
              style={{ display: "none" }}
              onChange={handleLicenseUpload}
            />

            <label htmlFor="licenseUpload" className="upload-cv-btn">
              Upload License (PDF)
            </label>
          </>
        )}
      </div>

      {/* BANK CARD */}
      <div className="payment-box">
        <h3>Bank / Benefit Card</h3>

        <div className="card-preview">
          <div className="bank-card teal-card">
            <div className="bank-chip"></div>

            <p className="card-number">
              {company.bankInfo?.cardNumber || "XXXX XXXX XXXX XXXX"}
            </p>

            <p className="card-holder">
              {company.bankInfo?.cardName || "Card Holder"}
            </p>

            <p className="bank-name-preview">
              {company.bankInfo?.bankName || "No Bank Selected"}
            </p>
          </div>
        </div>

        <div className="card-buttons">
          {!company.bankInfo?.cardNumber && (
            <button
              className="add-card-btn"
              onClick={() => setShowCardModal(true)}
            >
              + Add Card
            </button>
          )}

          {company.bankInfo?.cardNumber && (
            <>
              <button
                className="edit-card-btn"
                onClick={() => setShowCardModal(true)}
              >
                Edit Card
              </button>

              <button className="delete-card-btn" onClick={deleteBankCard}>
                Delete Card
              </button>
            </>
          )}
        </div>
      </div>

      {/* MODAL */}
      {showCardModal && (
        <div className="modal-overlay">
          <div className="modal-box">
            <div className="modal-header">
              <h3>Edit Card</h3>
              <button
                className="close-btn"
                onClick={() => setShowCardModal(false)}
              >
                ×
              </button>
            </div>

            <label>Select Bank</label>
            <div className="bank-radio-row">
              <label>
                <input
                  type="radio"
                  value="Bank Muscat"
                  {...register("selectedBank")}
                />
                Bank Muscat
              </label>

              <label>
                <input
                  type="radio"
                  value="Bank Dhofar"
                  {...register("selectedBank")}
                />
                Bank Dhofar
              </label>

              <label>
                <input type="radio" value="NBO" {...register("selectedBank")} />
                NBO
              </label>
            </div>
            <p className="error">{errors.selectedBank?.message}</p>

            <label>Card Number</label>
            <input
              className="modal-input"
              {...register("cardNumber")}
              onChange={(e) => {
                let v = e.target.value.replace(/\D/g, "");
                v = v.match(/.{1,4}/g)?.join(" ") || v;
                setValue("cardNumber", v);
              }}
            />
            <p className="error">{errors.cardNumber?.message}</p>

            <label>Cardholder Name</label>
            <input className="modal-input" {...register("cardName")} />
            <p className="error">{errors.cardName?.message}</p>

            <label>Expiration Date</label>
            <input
              type="month"
              className="modal-input"
              {...register("expiry")}
            />
            <p className="error">{errors.expiry?.message}</p>

            <label>CVV</label>
            <input
              type="password"
              maxLength="4"
              className="modal-input"
              {...register("cvv")}
            />
            <p className="error">{errors.cvv?.message}</p>

            <div className="modal-buttons">
              <button className="save-btn" onClick={handleSubmit(saveCardInfo)}>
                Save
              </button>
              <button className="clear-btn" onClick={() => reset()}>
                Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyProfile;
